// -------------------------------------------------
// 1. DATOS DE ENTRADA
// -------------------------------------------------
const entitydata = $input.first().json?.result?.entitydata || [];
// -------------------------------------------------
// 2. SOLO PUBLICADOS EN WEB Y NO VENDIDOS
// -------------------------------------------------
const publicados = entitydata.filter(v => {
  const isPublished = v.published_in_web === "1";
  const isNotSold = v.availability_status?.code !== "3" && 
                    v.availability_status?.code !== 3;  // Por si viene como número
  return isPublished && isNotSold;
});
// -------------------------------------------------
// 3. FORMATEAR VEHÍCULOS
// -------------------------------------------------
const formateados = publicados.map(v => {
  const prices = Array.isArray(v.prices) ? v.prices : [];
  const salePrice = prices.find(p => p.type === 'SALE_COST');
  return {
    id: v.id || null,
    marca: v.brand || '',
    modelo: v.model || '',
    version: v.version || '',
    anio: v.year || null,
    tipo: v.type?.code || '',
    combustible: v.fuel || '',
    transmision: v.transmission || '',
    kilometros: v.odometer || 0,
    color: v.color || '',
    estado: v.availability_status?.name || '',
    precio: salePrice ? Number(salePrice.value) : null,
    moneda: salePrice?.currency || 'MXN',
    publicado_web: true
  };
});
// -------------------------------------------------
// 4. AGRUPAR POR MARCA
// -------------------------------------------------
const porMarca = formateados.reduce((acc, v) => {
  if (!acc[v.marca]) {
    acc[v.marca] = [];
  }
  acc[v.marca].push(v);
  return acc;
}, {});
// -------------------------------------------------
// 5. DEVOLVER RESULTADO
// -------------------------------------------------
return [
  {
    json: {
      total_modelos: formateados.length,
      marcas: Object.keys(porMarca),
      modelos_por_marca: porMarca
    }
  }
];
